function buildQuiz(){const words=currentUnit.words;if(words.length<20){$('quizHint').textContent='This unit needs at least 20 words for the checkpoint.';return}quizItems=words.slice(0,20).map(w=>{const options=[w.word,...words.filter(x=>x.word!==w.word).sort(()=>Math.random()-.5).slice(0,3).map(x=>x.word)].sort(()=>Math.random()-.5);return{answer:w.word,prompt:(w.example||w.sourceExample||'').replace(w.word,'_____'),options}});$('quizQuestions').innerHTML=quizItems.map((q,i)=>`<div class="question"><b>QUESTION ${String(i+1).padStart(2,'0')}</b><p>${q.prompt}</p><div class="options">${q.options.map(o=>`<label><input type="radio" name="q${i}" value="${o}">${o}</label>`).join('')}</div></div>`).join('');$('quizProgressText').textContent=`0 / ${quizItems.length} answered`;$('quizProgressBar').style.width='0%';clearInterval(timerId);timerId=setInterval(()=>{$('quizTimer').textContent=formatTime(Math.floor((Date.now()-learnStarted)/1000))},1000)}
function populateEditor(){if(!$('editUnitSelect'))return;$('editUnitSelect').innerHTML=units.map(u=>`<option value="${u.id}">${u.title}</option>`).join('');loadEditorUnit()}
function loadEditorUnit(){const u=units.find(x=>String(x.id)===$('editUnitSelect').value)||units[0];$('editWordSelect').innerHTML=u.words.map((w,i)=>`<option value="${i}">${i+1}. ${w.word}</option>`).join('');loadEditorWord()}
function loadEditorWord(){const u=units.find(x=>String(x.id)===$('editUnitSelect').value)||units[0],w=u.words[Number($('editWordSelect').value)||0];if(!w)return;$('editImage').value=w.image||'';$('editCollocation').value=w.collocation||'';$('editSourceExample').value=w.sourceExample||'';$('editHelpfulExample').value=w.example||''}
async function saveWord(){const u=units.find(x=>String(x.id)===$('editUnitSelect').value),w=u.words[Number($('editWordSelect').value)||0];w.image=$('editImage').value.trim();w.collocation=$('editCollocation').value.trim();w.sourceExample=$('editSourceExample').value.trim();w.example=$('editHelpfulExample').value.trim();const saved=await api('/api/units',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(u)});if(saved){const idx=units.findIndex(x=>x.id===u.id);units[idx]=saved}$('editMessage').textContent='Saved. Students will see the updated card next round.';if(currentUnit&&currentUnit.id===u.id)renderCard()}
