function speakCurrentWord(){if(!('speechSynthesis' in window))return;speechSynthesis.cancel();const speak=()=>{const voices=speechSynthesis.getVoices();const british=voices.filter(v=>/^en-GB/i.test(v.lang));const female=british.find(v=>/female|susan|kate|serena|hazel|libby|samantha/i.test(v.name));const voice=female||british[0]||voices.find(v=>/^en/i.test(v.lang));const utterance=new SpeechSynthesisUtterance($('cardWord').textContent);utterance.lang='en-GB';utterance.rate=.82;utterance.pitch=1.04;if(voice)utterance.voice=voice;speechSynthesis.speak(utterance)};if(speechSynthesis.getVoices().length)speak();else speechSynthesis.onvoiceschanged=speak}
