let lastQuizSignature='';
function shuffleCopy(items){return [...items].sort(()=>Math.random()-.5)}
function buildQuiz(){const source=[...currentUnit.words];if(source.length<20){$('quizHint').textContent='This unit needs at least 20 words for the checkpoint.';return}let selected,questions,bank,signature;do{selected=shuffleCopy(source).slice(0,20);questions=shuffleCopy(selected);bank=shuffleCopy(selected);signature=questions.map(w=>w.word).join('|')+'::'+bank.map(w=>w.word).join('|')}while(signature===lastQuizSignature);lastQuizSignature=signature;quizItems=questions.map(w=>({answer:w.word,prompt:(w.example||w.sourceExample||'').replace(w.word,'_____')}));$('wordBank').innerHTML=bank.map(w=>`<span class="bank-word">${w.word}</span>`).join('');$('quizQuestions').innerHTML=quizItems.map((q,i)=>`<div class="question"><b>QUESTION ${String(i+1).padStart(2,'0')}</b><p>${q.prompt}</p><input class="answer-input" name="q${i}" autocomplete="off" spellcheck="false" placeholder="Type the missing word"></div>`).join('');$('quizProgressText').textContent='0 / 20 answered';$('quizProgressBar').style.width='0%';clearInterval(timerId);timerId=setInterval(()=>{$('quizTimer').textContent=formatTime(Math.floor((Date.now()-learnStarted)/1000))},1000)}

function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}
function escapeRegExp(value){return value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function makeQuizPrompt(w){const candidates=[w.sourceExample,w.example].filter(Boolean);const pattern=new RegExp('\\b'+escapeRegExp(w.word)+'\\b','i');for(const text of candidates){if(pattern.test(text))return text.replace(pattern,'_____')}return `This means "${w.definition}". The best word is _____.`}
function buildQuiz(){const source=[...currentUnit.words];if(source.length<20){$('quizHint').textContent='This unit needs at least 20 words for the checkpoint.';return}let selected,questions,bank,signature;do{selected=shuffleCopy(source).slice(0,20);questions=shuffleCopy(selected);bank=shuffleCopy(selected);signature=questions.map(w=>w.word).join('|')+'::'+bank.map(w=>w.word).join('|')}while(signature===lastQuizSignature);lastQuizSignature=signature;quizItems=questions.map(w=>({answer:w.word,prompt:makeQuizPrompt(w)}));$('wordBank').innerHTML=bank.map(w=>`<span class="bank-word" data-word="${escapeHtml(w.word)}" role="button" tabindex="0">${escapeHtml(w.word)}</span>`).join('');$('quizQuestions').innerHTML=quizItems.map((q,i)=>`<div class="question"><b>QUESTION ${String(i+1).padStart(2,'0')}</b><p>${escapeHtml(q.prompt)}</p><input class="answer-input" name="q${i}" autocomplete="off" spellcheck="false" placeholder="Type the missing word"></div>`).join('');$('quizProgressText').textContent='0 / 20 answered';$('quizProgressBar').style.width='0%';clearInterval(timerId);timerId=setInterval(()=>{$('quizTimer').textContent=formatTime(Math.floor((Date.now()-learnStarted)/1000))},1000)}
