// Keep a browser backup even when the shared service is asleep or temporarily unavailable.
function saveLocalAttempt(record){const all=JSON.parse(localStorage.getItem('wordSprintAttempts')||'[]');all.unshift({...record,at:new Date().toLocaleString()});localStorage.setItem('wordSprintAttempts',JSON.stringify(all))}
$('submitQuiz').addEventListener('click',()=>{const answers=quizItems.map((_,i)=>document.querySelector(`input[name=q${i}]`));if(answers.some(x=>!x||!x.value.trim()))return;const correct=answers.reduce((n,x,i)=>n+(normAnswer(x.value)===normAnswer(quizItems[i].answer)?1:0),0);saveLocalAttempt({name:currentName,unit:currentUnit.title,score:Math.round(correct/quizItems.length*100),total:100,seconds:Math.floor((Date.now()-learnStarted)/1000),attempt:attemptNo+1,passed:correct/quizItems.length>=.7})},{capture:true});
$('teacherLoginForm').onsubmit=async e=>{
  e.preventDefault();
  const username=$('teacherUsername').value.trim();
  const password=$('teacherPassword').value;
  const login=await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});
  if(!login||!login.token){
    $('teacherLoginError').textContent='Incorrect username or password.';
    return;
  }
  teacherToken=login.token;
  show('teacherView');
  populateEditor();
  loadTeacher();
};
